#include "iv.hpp"
#include <cmath>
#include <algorithm>
#include <limits>

namespace model {

// Black-Scholes price function
double bs_price(double S, double K, double r, double q, double sigma, double T, bool is_call) {
    if (S <= 0 || K <= 0 || sigma <= 0 || T <= 0) {
        return 0.0;
    }

    const double d1 = (std::log(S / K) + (r - q + 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));
    const double d2 = d1 - sigma * std::sqrt(T);

    const double N_d1 = is_call ? 
        0.5 * (1.0 + std::erf(d1 / std::sqrt(2.0))) : 
        0.5 * (1.0 - std::erf(d1 / std::sqrt(2.0)));

    const double N_d2 = is_call ? 
        0.5 * (1.0 + std::erf(d2 / std::sqrt(2.0))) : 
        0.5 * (1.0 - std::erf(d2 / std::sqrt(2.0)));

    const double price = is_call ? 
        S * std::exp(-q * T) * N_d1 - K * std::exp(-r * T) * N_d2 :
        K * std::exp(-r * T) * N_d2 - S * std::exp(-q * T) * N_d1;

    return price;
}

// Black-Scholes vega function (derivative of price w.r.t. sigma)
double bs_vega(double S, double K, double r, double q, double sigma, double T) {
    if (S <= 0 || K <= 0 || sigma <= 0 || T <= 0) {
        return 0.0;
    }

    const double d1 = (std::log(S / K) + (r - q + 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));
    const double pdf_d1 = 1.0 / std::sqrt(2.0 * M_PI) * std::exp(-0.5 * d1 * d1);

    return S * std::exp(-q * T) * std::sqrt(T) * pdf_d1;
}

// Implied volatility solver using a robust hybrid approach
double implied_vol(double price, double S, double K, double r, double q, double T, bool is_call) {
    // Handle edge cases
    if (S <= 0 || K <= 0 || T <= 0 || sigma <= 0) {
        return std::numeric_limits<double>::quiet_NaN();
    }

    // Calculate intrinsic value
    const double intrinsic = is_call ? std::max(0.0, S - K) : std::max(0.0, K - S);
    const double discounted_intrinsic = is_call ? std::max(0.0, S * std::exp(-q * T) - K * std::exp(-r * T)) : 
                                              std::max(0.0, K * std::exp(-r * T) - S * std::exp(-q * T));

    // If price is below intrinsic value, no valid volatility exists
    if (price <= discounted_intrinsic) {
        return std::numeric_limits<double>::quiet_NaN();
    }

    // If price is very close to intrinsic, return a small volatility
    if (price - discounted_intrinsic < 1e-15) {
        return 1e-8;
    }

    // Calculate the maximum possible price (upper bound)
    const double max_price = is_call ? S * std::exp(-q * T) : K * std::exp(-r * T);
    if (price >= max_price) {
        return std::numeric_limits<double>::quiet_NaN();
    }

