#include <random>
#include <cmath>

int main() {
    using namespace model;

    // Performance test - run 1 million calls
    const int num_calls = 1000000;

    // Random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> sigma_dist(0.01, 5.0);
    std::uniform_real_distribution<double> T_dist(1.0/365.0, 30.0);
    std::uniform_real_distribution<double> moneyness_dist(-4.0, 4.0);

    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < num_calls; ++i) {
        // Generate random parameters
        double S = 100.0;
        double K = S * std::exp(moneyness_dist(gen) * std::sqrt(T_dist(gen)));
        double r = 0.05;
        double q = 0.02;
        double sigma = sigma_dist(gen);
        double T = T_dist(gen);
        bool is_call = (i % 2 == 0);

        // Calculate price
        double price = bs_price(S, K, r, q, sigma, T, is_call);

        // Calculate implied volatility
        double implied_sigma = implied_vol(price, S, K, r, q, T, is_call);

        // Check if result is valid
        if (std::isnan(implied_sigma)) {
            std::cout << "Warning: NaN result at iteration " << i << std::endl;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);

    std::cout << "Executed " << num_calls << " calls in " << duration.count() << " ms" << std::endl;
    std::cout << "Average time per call: " << (double)duration.count() / num_calls * 1000 << " microseconds" << std::endl;

    return 0;
}

