int main() {
    using namespace model;

    // Test a few specific cases to verify correctness
    std::vector<std::tuple<double, double, double, double, double, double, bool>> test_cases = {
        // {S, K, r, q, sigma, T, is_call}
        {100.0, 100.0, 0.05, 0.02, 0.2, 1.0, true},
        {100.0, 100.0, 0.05, 0.02, 0.3, 1.0, true},
        {110.0, 100.0, 0.05, 0.02, 0.25, 0.5, true},
        {90.0, 100.0, 0.05, 0.02, 0.3, 2.0, false},
        {100.0, 100.0, 0.05, 0.02, 0.15, 0.25, true},
        {120.0, 100.0, 0.05, 0.02, 0.4, 3.0, true},
    };

    bool all_passed = true;

    for (size_t i = 0; i < test_cases.size(); ++i) {
        auto [S, K, r, q, sigma, T, is_call] = test_cases[i];

        // Calculate price with known volatility
        double price = bs_price(S, K, r, q, sigma, T, is_call);

        // Calculate implied volatility
        double implied_sigma = implied_vol(price, S, K, r, q, T, is_call);

        // Check if result is valid and accurate
        if (std::isnan(implied_sigma)) {
            std::cout << "Test " << i+1 << " FAILED: NaN result" << std::endl;
            all_passed = false;
        } else {
            double error = std::abs(implied_sigma - sigma) / sigma;
            if (error > 1e-7) {
                std::cout << "Test " << i+1 << " FAILED: Error = " << error << " (expected ~" << sigma << ", got " << implied_sigma << ")" << std::endl;
                all_passed = false;
            } else {
                std::cout << "Test " << i+1 << " PASSED: sigma=" << sigma << ", implied=" << implied_sigma << ", error=" << error << std::endl;
            }
        }
    }

    // Test edge cases
    std::cout << "\nTesting edge cases:" << std::endl;

    // Very small time
    double price = bs_price(100.0, 100.0, 0.05, 0.02, 0.2, 1e-6, true);
    double implied_sigma = implied_vol(price, 100.0, 100.0, 0.05, 0.02, 1e-6, true);
    std::cout << "Small time case: price=" << price << ", implied=" << implied_sigma << std::endl;

    // Deep ITM
    price = bs_price(120.0, 100.0, 0.05, 0.02, 0.2, 1.0, true);
    implied_sigma = implied_vol(price, 120.0, 100.0, 0.05, 0.02, 1.0, true);
    std::cout << "Deep ITM case: price=" << price << ", implied=" << implied_sigma << std::endl;

    // Deep OTM
    price = bs_price(80.0, 100.0, 0.05, 0.02, 0.2, 1.0, true);
    implied_sigma = implied_vol(price, 80.0, 100.0, 0.05, 0.02, 1.0, true);
    std::cout << "Deep OTM case: price=" << price << ", implied=" << implied_sigma << std::endl;

    if (all_passed) {
        std::cout << "\nAll tests passed!" << std::endl;
    } else {
        std::cout << "\nSome tests failed!" << std::endl;
    }

    return 0;
}

